const app=document.querySelector('#app');let questions=[],answers={},index=0,mode='study',checked={},deadline=0,timer=null,finished=false;
let history=[];try{history=JSON.parse(localStorage.getItem('clinicalab-history')||'[]')}catch{}
const topics=[...new Set(bank.map(q=>q.topic))];
function home(){clearInterval(timer);app.innerHTML=`<section class="hero"><div><span class="eyebrow">DEL CONOCIMIENTO AL CRITERIO CLÍNICO</span><h1>Entrena tu mirada.<br>Fundamenta tu<br><span style="color:#478367">próxima respuesta.</span></h1><p class="lead">Practica con casos del WISC-V, toma decisiones y comprende el razonamiento detrás de cada respuesta.</p><div class="stats"><div><b>20</b><span>casos originales</span></div><div><b>5</b><span>áreas de práctica</span></div><div><b>2</b><span>modos de aprendizaje</span></div></div><p class="note">Para estudiantes de Psicología Clínica de 8.º semestre que buscan reforzar evaluación y razonamiento clínico en su preparación para el CACES.</p></div><section class="panel"><span class="eyebrow">TU SESIÓN DE HOY</span><h2>Configura tu práctica</h2><label for="mode">¿Cómo quieres practicar?</label><select id="mode"><option value="study">Estudio · explicación tras cada respuesta</option><option value="exam">Examen · resultados al finalizar</option></select><label for="topic">Área de enfoque</label><select id="topic"><option value="all">Todas las áreas</option>${topics.map(t=>`<option>${t}</option>`).join('')}</select><label for="count">Extensión de la sesión</label><select id="count"><option value="10">Hasta 10 preguntas</option><option value="20">Banco completo · hasta 20 preguntas</option><option value="5">Repaso breve · hasta 5 preguntas</option></select><button class="primary" onclick="start()">Comenzar práctica →</button><p class="note">En examen: 90 segundos por pregunta. Tiempo elegido para esta práctica; no representa condiciones oficiales.</p></section></section><section class="features"><article><span class="num">01 / COMPRENDE</span><h3>Casos con contexto</h3><p class="muted">Perfiles ficticios, antecedentes y dilemas de evaluación.</p></article><article><span class="num">02 / ARGUMENTA</span><h3>Aprende de cada decisión</h3><p class="muted">Una respuesta mejor fundamentada y su explicación.</p></article><article><span class="num">03 / REFUERZA</span><h3>Vuelve a tus errores</h3><p class="muted">Revisa resultados por área y practica lo que necesitas.</p></article></section><section class="panel"><h3>Tu recorrido</h3>${history.length?history.slice(-5).reverse().map(h=>`<p class="note">${new Date(h.date).toLocaleString('es-EC')} · ${h.mode==='exam'?'Examen':'Estudio'} · ${h.score}/${h.total} correctas</p>`).join('')+'<button class="textbtn" onclick="eraseHistory()">Borrar historial local</button>':'<p class="muted">Tu primera sesión empieza aquí. Los últimos resultados se guardan solo en este navegador.</p>'}<details><summary>Alcance y referencias</summary><p class="note">Este es un módulo de práctica de WISC-V, no un simulacro integral ni un banco oficial del CACES. No se ha verificado una correspondencia específica de estas preguntas con el temario vigente. La puntuación del simulador no predice aprobación. Las puntuaciones clínicas mostradas son ficticias; no se calculan diagnósticos ni puntuaciones reales. Consulta siempre la adaptación y el manual autorizados que correspondan a tu contexto.</p><ul><li><a href="https://www.caces.gob.ec/psicologia-clinica/" target="_blank" rel="noopener">CACES · Psicología Clínica y documentos de referencia</a></li><li><a href="https://www.pearsonclinical.es/es-es/Tienda/Evaluaciones-Profesionales/Inteligencia-%26-Neuropsicolog%C3%ADa/Escala-de-inteligencia-de-Wechsler-para-ni%C3%B1os-V/p/P100200013" target="_blank" rel="noopener">Pearson · WISC-V y manuales autorizados</a></li><li><a href="https://www.cedeti.cl/wp-content/uploads/2024/03/Gui%CC%81a-pra%CC%81ctica-WISC-V-digital-febrero.pdf" target="_blank" rel="noopener">CEDETi UC · Guía práctica de aplicación e interpretación</a></li></ul><p class="note">Referencias generales, no validación externa del banco. Revisión de enlaces: 4 de noviembre de 2026. Para uso docente evaluativo, se recomienda revisión del contenido por el equipo académico.</p></details></section>`}
function shuffle(a){for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function start(ids){mode=ids?'study':document.querySelector('#mode').value;const topic=ids?'all':document.querySelector('#topic').value;const n=ids?ids.length:+document.querySelector('#count').value;questions=shuffle(bank.filter(q=>ids?ids.includes(q.id):topic==='all'||q.topic===topic).slice()).slice(0,n);answers={};checked={};index=0;finished=false;deadline=Date.now()+questions.length*90000;clearInterval(timer);if(mode==='exam')timer=setInterval(tick,1000);render()}
function tick(){let el=document.querySelector('#clock');const left=Math.max(0,Math.ceil((deadline-Date.now())/1000));if(el)el.textContent=`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`;if(!left)finish()}
function selectAnswer(n){if(checked[index])return;answers[index]=n;render()}
function render(){const q=questions[index],revealed=!!checked[index];app.innerHTML=`<div class="quiztop"><div><span class="eyebrow">${mode==='exam'?'MODO EXAMEN':'MODO ESTUDIO'}</span><h2>Un caso. Una decisión.</h2></div><span class="pill">${mode==='exam'?'<span id="clock"></span> · ':''}${Object.keys(answers).length}/${questions.length} respondidas</span></div><div class="progress"><i style="width:${(index+1)/questions.length*100}%"></i></div><div class="quizgrid"><aside class="case"><span class="eyebrow">CASO ${String(index+1).padStart(2,'0')} · ${q.topic}</span><p>${q.case}</p><span class="note">Caso ficticio · Elige la mejor respuesta con los datos disponibles.</span></aside><section class="panel"><h3>${q.question}</h3>${q.options.map((o,n)=>`<button class="option ${answers[index]===n?'selected':''} ${revealed&&n===q.answer?'correct':''} ${revealed&&answers[index]===n&&n!==q.answer?'wrong':''}" onclick="selectAnswer(${n})" ${revealed?'disabled':''}><span>${'ABCD'[n]}</span>${o}</button>`).join('')}${revealed?`<div class="feedback" role="status"><b>${answers[index]===q.answer?'Respuesta correcta':'Respuesta correcta: '+ 'ABCD'[q.answer]}</b><p>${q.why}</p></div>`:''}<div class="actions"><button class="secondary" onclick="move(-1)" ${index===0?'disabled':''}>← Anterior</button>${mode==='study'&&!revealed?`<button onclick="check()" ${answers[index]===undefined?'disabled':''}>Comprobar</button>`:`<button onclick="${index===questions.length-1?'finish()':'move(1)'}">${index===questions.length-1?'Ver resultados':'Siguiente →'}</button>`}</div></section></div><nav class="navdots" aria-label="Navegar preguntas">${questions.map((_,i)=>`<button aria-label="Pregunta ${i+1}${answers[i]!==undefined?', respondida':''}" class="${i===index?'active':''}" onclick="go(${i})">${i+1}${answers[i]!==undefined?' •':''}</button>`).join('')}</nav><button class="textbtn" onclick="finish()">Finalizar sesión y ver resultados</button>`;if(mode==='exam')tick()}
function check(){if(answers[index]!==undefined){checked[index]=true;render()}}
function move(d){index+=d;render()}function go(i){index=i;render()}
function finish(){if(finished)return;finished=true;clearInterval(timer);const correct=questions.filter((q,i)=>answers[i]===q.answer).length;const errors=questions.filter((q,i)=>answers[i]!==q.answer).map(q=>q.id);history.push({date:Date.now(),mode,score:correct,total:questions.length});history=history.slice(-20);try{localStorage.setItem('clinicalab-history',JSON.stringify(history))}catch{}app.innerHTML=`<span class="eyebrow">SESIÓN COMPLETADA</span><h1>Cada caso deja<br>un aprendizaje.</h1><div class="quizgrid"><section class="panel dark"><span>Tu resultado de práctica</span><div class="score">${Math.round(correct/questions.length*100)}<small style="font-size:25px">%</small></div><p>${correct} correctas · ${questions.length-correct} incorrectas o sin responder</p><p class="muted">Este resultado refleja esta sesión; no es una nota de aprobación del CACES.</p><button class="secondary" onclick="home()">Nueva sesión</button> ${errors.length?`<button class="secondary" onclick='start(${JSON.stringify(errors)})'>Repasar errores</button>`:''}</section><section class="panel"><h3>Desempeño por área</h3>${topics.filter(t=>questions.some(q=>q.topic===t)).map(t=>{const qs=questions.map((q,i)=>({q,i})).filter(x=>x.q.topic===t);return `<div class="topicrow"><span>${t}</span><b>${qs.filter(x=>answers[x.i]===x.q.answer).length}/${qs.length}</b></div>`}).join('')}</section></div><h2>Revisión de respuestas</h2>${questions.map((q,i)=>`<article class="review"><span class="eyebrow">${i+1} · ${q.topic} · ${answers[i]===q.answer?'CORRECTA':answers[i]===undefined?'SIN RESPONDER':'POR REFORZAR'}</span><p>${q.case}</p><h3>${q.question}</h3><p class="muted">Tu respuesta: ${answers[i]===undefined?'Sin responder':q.options[answers[i]]}</p><p><b>Respuesta correcta: ${q.options[q.answer]}</b></p><p>${q.why}</p></article>`).join('')}`;window.scrollTo(0,0)}
function eraseHistory(){history=[];try{localStorage.removeItem('clinicalab-history')}catch{}home()}home();
